import{_ as t,o,c as a,a2 as n}from"./chunks/framework.D9DTPhg1.js";const m=JSON.parse('{"title":"Exceptions","description":"","frontmatter":{},"headers":[],"relativePath":"reference/exceptions.md","filePath":"website/reference/exceptions.md"}'),i={name:"reference/exceptions.md"};function r(c,e,d,s,l,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="exceptions" tabindex="-1">Exceptions <a class="header-anchor" href="#exceptions" aria-label="Permalink to &quot;Exceptions&quot;">​</a></h1><p>Every exception that Prism throws implements <code>Prism\\Exception\\PrismException</code>, and an interface per package: <code>DbalException</code>, <code>OrmException</code>, <code>MigrationsException</code>, <code>BundleException</code>. Catch one of them to handle all the errors of a package.</p><p>The messages are in English and name what is concerned: the entity, the field, the identifier, the table. They never contain a bound value or a password, which may be sensitive.</p><h2 id="orm" tabindex="-1">ORM <a class="header-anchor" href="#orm" aria-label="Permalink to &quot;ORM&quot;">​</a></h2><p><code>Prism\\Orm\\Exception</code>, package <code>prism-orm/orm</code>.</p><h3 id="mappingexception" tabindex="-1"><code>MappingException</code> <a class="header-anchor" href="#mappingexception" aria-label="Permalink to &quot;`MappingException`&quot;">​</a></h3><p>A mapping attribute has an invalid argument, or the mapping of an entity is invalid: no identifier, a <code>\\DateTime</code> property, a contradiction between <code>nullable</code> and the PHP type, a relation whose other side does not match... The message lists every error with its class and field.</p><p><strong>Fix:</strong> follow the message; <code>db:schema:validate</code> lists all the errors of all the entities at once.</p><h3 id="invalidentitystateexception" tabindex="-1"><code>InvalidEntityStateException</code> <a class="header-anchor" href="#invalidentitystateexception" aria-label="Permalink to &quot;`InvalidEntityStateException`&quot;">​</a></h3><p>An operation that the state of the entity does not allow: <code>remove()</code> on a new entity, <code>persist()</code> on a detached one, for example.</p><p><strong>Fix:</strong> see the <a href="/prism/guide/entity-manager#entity-states">entity states</a>. A detached entity is loaded again with <code>find()</code>.</p><h3 id="unpersistedrelationexception" tabindex="-1"><code>UnpersistedRelationException</code> <a class="header-anchor" href="#unpersistedrelationexception" aria-label="Permalink to &quot;`UnpersistedRelationException`&quot;">​</a></h3><p>At flush, a new entity is reachable through a relation of a managed one, but was never persisted. The message gives the entity, the field and the path. Nothing was written.</p><p><strong>Fix:</strong> <code>persist()</code> it, or add <code>cascade: [Prism\\Cascade::Persist]</code> to the relation.</p><h3 id="cyclicdependencyexception" tabindex="-1"><code>CyclicDependencyException</code> <a class="header-anchor" href="#cyclicdependencyexception" aria-label="Permalink to &quot;`CyclicDependencyException`&quot;">​</a></h3><p>The <code>INSERT</code> statements of a flush cannot be ordered: the entities reference each other in a cycle in which no foreign key is nullable.</p><p><strong>Fix:</strong> make one foreign key of the cycle nullable. Prism then inserts it as <code>NULL</code> and sets it with an <code>UPDATE</code> afterwards.</p><h3 id="reentrantflushexception" tabindex="-1"><code>ReentrantFlushException</code> <a class="header-anchor" href="#reentrantflushexception" aria-label="Permalink to &quot;`ReentrantFlushException`&quot;">​</a></h3><p><code>flush()</code> was called during a flush, from an event listener or a lifecycle callback.</p><p><strong>Fix:</strong> change entities in <code>PreFlushEvent</code>, <code>OnFlushEvent</code> or <code>PreUpdateEvent</code>, which the running flush writes; or flush after it returns.</p><h3 id="orphanreattachedexception" tabindex="-1"><code>OrphanReattachedException</code> <a class="header-anchor" href="#orphanreattachedexception" aria-label="Permalink to &quot;`OrphanReattachedException`&quot;">​</a></h3><p>An entity removed from a collection with <code>orphanRemoval</code> was attached to another parent in the same flush, while it is going to be deleted.</p><p><strong>Fix:</strong> flush the removal first, or move the entity without <code>orphanRemoval</code>.</p><h3 id="entitynotfoundexception" tabindex="-1"><code>EntityNotFoundException</code> <a class="header-anchor" href="#entitynotfoundexception" aria-label="Permalink to &quot;`EntityNotFoundException`&quot;">​</a></h3><p>The row of an entity does not exist, or not anymore: a reference that loads, <code>refresh()</code>, <code>lock()</code>. The message gives the class and the identifier.</p><p><strong>Fix:</strong> use <code>find()</code>, which returns <code>null</code>, when the row may be missing.</p><h3 id="optimisticlockexception" tabindex="-1"><code>OptimisticLockException</code> <a class="header-anchor" href="#optimisticlockexception" aria-label="Permalink to &quot;`OptimisticLockException`&quot;">​</a></h3><p>The row changed since it was loaded: the <code>UPDATE</code> or <code>DELETE</code> checked against the <a href="/prism/reference/attributes#version"><code>#[Version]</code></a> field matched no row. Also thrown by an optimistic <code>lock()</code> on an outdated version, or on an entity without a version.</p><p><strong>Fix:</strong> load the entity again and reapply the change, or tell the user that someone else changed it.</p><h3 id="transactionrequiredexception" tabindex="-1"><code>TransactionRequiredException</code> <a class="header-anchor" href="#transactionrequiredexception" aria-label="Permalink to &quot;`TransactionRequiredException`&quot;">​</a></h3><p>A pessimistic <code>lock()</code> outside a transaction.</p><p><strong>Fix:</strong> call it inside <code>wrapInTransaction()</code>.</p><h3 id="nonuniqueresultexception" tabindex="-1"><code>NonUniqueResultException</code> <a class="header-anchor" href="#nonuniqueresultexception" aria-label="Permalink to &quot;`NonUniqueResultException`&quot;">​</a></h3><p><code>getOneOrNull()</code> on a query that returns several entities.</p><p><strong>Fix:</strong> add a condition, or use <code>getResult()</code> or <code>limit(1)</code>.</p><h3 id="queryexception" tabindex="-1"><code>QueryException</code> <a class="header-anchor" href="#queryexception" aria-label="Permalink to &quot;`QueryException`&quot;">​</a></h3><p>A typed query is invalid: an alias that is not part of the query, a stale metamodel, a fetch join of an alias that is not fetched, a <code>limit()</code> with a fetch-joined collection, an entity query with a <code>groupBy()</code>, a selected field that is not grouped, a <code>selectInto()</code> that does not match its DTO, an invalid JSON path, a pagination without order or with a <code>limit()</code>.</p><p><strong>Fix:</strong> follow the message. PHPStan reports the <code>selectInto()</code> cases during analysis; in development, a stale metamodel is regenerated when the kernel boots.</p><h3 id="invalidargumentexception" tabindex="-1"><code>InvalidArgumentException</code> <a class="header-anchor" href="#invalidargumentexception" aria-label="Permalink to &quot;`InvalidArgumentException`&quot;">​</a></h3><p>An argument refused by an ORM API: a batch size out of range, a criterion that holds an unsaved entity, a filter name that already exists or does not, the tenant filter disabled, <code>restore()</code> on an entity that is not soft-deletable.</p><p><strong>Fix:</strong> follow the message.</p><h3 id="metamodelexception" tabindex="-1"><code>MetamodelException</code> <a class="header-anchor" href="#metamodelexception" aria-label="Permalink to &quot;`MetamodelException`&quot;">​</a></h3><p>The metamodel cannot be written in its directory.</p><p><strong>Fix:</strong> make the directory writable, or choose another one (<code>metamodel.dir</code>, <code>--dir</code>).</p><h3 id="vectordimensionmismatchexception" tabindex="-1"><code>VectorDimensionMismatchException</code> <a class="header-anchor" href="#vectordimensionmismatchexception" aria-label="Permalink to &quot;`VectorDimensionMismatchException`&quot;">​</a></h3><p>At flush, a vector has more or fewer components than the <code>dimensions</code> of its column. The message gives the entity, the field and both dimensions. Nothing was written.</p><p><strong>Fix:</strong> store the output of the embedding model the column was created for. A different model needs a new column size, or a migration.</p><h3 id="embeddingexception" tabindex="-1"><code>EmbeddingException</code> <a class="header-anchor" href="#embeddingexception" aria-label="Permalink to &quot;`EmbeddingException`&quot;">​</a></h3><p>An <code>#[EmbeddedVector]</code> could not be computed: its provider name is not registered, the provider failed (network, quota), or it returned the wrong number of vectors or the wrong dimension. The rows stay stale, left out of <code>nearest()</code>. A <code>ComputeEmbedding</code> message is retried.</p><p><strong>Fix:</strong> register the provider under the name the attribute gives (<code>model: &#39;default&#39;</code>), and check that its dimension is the one of the column. Then run <code>db:embeddings:compute</code>.</p><h3 id="missingtenantexception" tabindex="-1"><code>MissingTenantException</code> <a class="header-anchor" href="#missingtenantexception" aria-label="Permalink to &quot;`MissingTenantException`&quot;">​</a></h3><p>An operation on a <code>#[Tenanted]</code> entity without a current tenant. Prism has no implicit &quot;all tenants&quot; mode.</p><p><strong>Fix:</strong> set the tenant (<code>setTenantId()</code>, <code>runAs()</code>), or use <code>runAsSystem()</code> for an operation on every tenant. See <a href="/prism/guide/multi-tenancy#no-tenant-no-query">Multi-tenancy</a>.</p><h3 id="tenantmismatchexception" tabindex="-1"><code>TenantMismatchException</code> <a class="header-anchor" href="#tenantmismatchexception" aria-label="Permalink to &quot;`TenantMismatchException`&quot;">​</a></h3><p>The tenant property of an entity holds another tenant than the current one, or was changed: the tenant of a row never changes.</p><p><strong>Fix:</strong> let Prism fill the tenant property; to create an entity for another tenant, do it inside <code>runAs()</code>.</p><h3 id="crosstenantrelationexception" tabindex="-1"><code>CrossTenantRelationException</code> <a class="header-anchor" href="#crosstenantrelationexception" aria-label="Permalink to &quot;`CrossTenantRelationException`&quot;">​</a></h3><p>At flush, a relation links two tenanted entities of different tenants. Refused even in system mode.</p><p><strong>Fix:</strong> link entities of the same tenant; a shared reference row belongs to an entity marked <code>#[Tenanted(global: true)]</code>.</p><h3 id="tenantswitchexception" tabindex="-1"><code>TenantSwitchException</code> <a class="header-anchor" href="#tenantswitchexception" aria-label="Permalink to &quot;`TenantSwitchException`&quot;">​</a></h3><p>The tenant changed while the unit of work had unsaved changes. When entering <code>runAs()</code> or <code>runAsSystem()</code>, the switch is refused and nothing is lost; when leaving, the changes made inside are discarded, never written under another tenant.</p><p><strong>Fix:</strong> flush before entering, and before leaving.</p><h3 id="unfilteredtenantqueryexception" tabindex="-1"><code>UnfilteredTenantQueryException</code> <a class="header-anchor" href="#unfilteredtenantqueryexception" aria-label="Permalink to &quot;`UnfilteredTenantQueryException`&quot;">​</a></h3><p>Raw SQL on a tenanted table without a condition on its tenant column, a <code>TRUNCATE</code>, or SQL that the guard cannot analyze. Thrown by the tenant guard in <code>exception</code> mode.</p><p><strong>Fix:</strong> add <code>tenant_id = ?</code> to the <code>WHERE</code> or <code>ON</code> of each tenanted table, or run the query in <code>runAsSystem()</code> if it really concerns every tenant. See <a href="/prism/guide/multi-tenancy#raw-sql">Raw SQL</a>.</p><h2 id="dbal" tabindex="-1">DBAL <a class="header-anchor" href="#dbal" aria-label="Permalink to &quot;DBAL&quot;">​</a></h2><p><code>Prism\\Dbal\\Exception</code>, package <code>prism-orm/dbal</code>.</p><h3 id="connectionfailedexception" tabindex="-1"><code>ConnectionFailedException</code> <a class="header-anchor" href="#connectionfailedexception" aria-label="Permalink to &quot;`ConnectionFailedException`&quot;">​</a></h3><p>The database connection could not be opened.</p><p><strong>Fix:</strong> check the host, the credentials and that the server runs; the message is the driver&#39;s.</p><h3 id="invalidurlexception" tabindex="-1"><code>InvalidUrlException</code> <a class="header-anchor" href="#invalidurlexception" aria-label="Permalink to &quot;`InvalidUrlException`&quot;">​</a></h3><p>The database URL cannot be read or is incomplete. The password never appears in the message.</p><p><strong>Fix:</strong> use Symfony&#39;s format, <code>driver://user:pass@host:port/db?serverVersion=x</code>.</p><h3 id="unsupportedplatformexception" tabindex="-1"><code>UnsupportedPlatformException</code> <a class="header-anchor" href="#unsupportedplatformexception" aria-label="Permalink to &quot;`UnsupportedPlatformException`&quot;">​</a></h3><p>The <code>serverVersion</code> cannot be read, or is older than what Prism supports: MySQL 8.0, MariaDB 11.8, PostgreSQL 15, SQLite 3.40.</p><p><strong>Fix:</strong> set <code>serverVersion</code> to the real version of the server, which must be supported.</p><h3 id="queryfailedexception" tabindex="-1"><code>QueryFailedException</code> <a class="header-anchor" href="#queryfailedexception" aria-label="Permalink to &quot;`QueryFailedException`&quot;">​</a></h3><p>The server refused a query. The exception carries the SQL and the SQLSTATE, never the bound values.</p><p><strong>Fix:</strong> read the SQLSTATE: a constraint violation, a missing table (run the migrations), a syntax error in your own SQL.</p><h3 id="abortedtransactionexception" tabindex="-1"><code>AbortedTransactionException</code> <a class="header-anchor" href="#abortedtransactionexception" aria-label="Permalink to &quot;`AbortedTransactionException`&quot;">​</a></h3><p>Under PostgreSQL, a failed query invalidated the transaction: a <code>COMMIT</code> would silently become a <code>ROLLBACK</code>. Prism rolls back and says so.</p><p><strong>Fix:</strong> handle the first failure; to continue a transaction after an expected failure, run the risky query inside a nested transaction (a savepoint).</p><h3 id="noactivetransactionexception" tabindex="-1"><code>NoActiveTransactionException</code> <a class="header-anchor" href="#noactivetransactionexception" aria-label="Permalink to &quot;`NoActiveTransactionException`&quot;">​</a></h3><p><code>commit()</code> or <code>rollBack()</code> without an open transaction, or after MySQL or MariaDB committed it implicitly with a DDL statement.</p><p><strong>Fix:</strong> pair each <code>beginTransaction()</code> with one <code>commit()</code> or <code>rollBack()</code>, or use <code>transactional()</code>.</p><h3 id="conversionexception" tabindex="-1"><code>ConversionException</code> <a class="header-anchor" href="#conversionexception" aria-label="Permalink to &quot;`ConversionException`&quot;">​</a></h3><p>A value cannot be converted between PHP and the database: a <code>float</code> for a <code>decimal</code>, a mutable <code>\\DateTime</code>, a number with more significant digits than the column holds, invalid JSON... The message names the type and the expected form, never the value.</p><p><strong>Fix:</strong> pass the PHP type of the column: a <code>string</code> for a <code>decimal</code>, a <code>\\DateTimeImmutable</code> for a date.</p><h3 id="invalidparameterexception" tabindex="-1"><code>InvalidParameterException</code> <a class="header-anchor" href="#invalidparameterexception" aria-label="Permalink to &quot;`InvalidParameterException`&quot;">​</a></h3><p>A value that cannot be bound (not a scalar), positional and named parameters mixed, an invalid savepoint name or JSON path.</p><p><strong>Fix:</strong> follow the message.</p><h3 id="invalidqueryexception" tabindex="-1"><code>InvalidQueryException</code> <a class="header-anchor" href="#invalidqueryexception" aria-label="Permalink to &quot;`InvalidQueryException`&quot;">​</a></h3><p>A query of the DBAL query builder is inconsistent: a clause that this kind of query does not allow, no table, an empty <code>SELECT</code> or <code>IN</code> list, a comparison with <code>null</code> (use <code>isNull()</code>).</p><p><strong>Fix:</strong> follow the message.</p><h3 id="invalididentifierexception" tabindex="-1"><code>InvalidIdentifierException</code> <a class="header-anchor" href="#invalididentifierexception" aria-label="Permalink to &quot;`InvalidIdentifierException`&quot;">​</a></h3><p>A table, column or index name that cannot be quoted safely on the platform: empty, with invalid characters, or too long.</p><p><strong>Fix:</strong> rename it.</p><h3 id="invalidschemaexception" tabindex="-1"><code>InvalidSchemaException</code> <a class="header-anchor" href="#invalidschemaexception" aria-label="Permalink to &quot;`InvalidSchemaException`&quot;">​</a></h3><p>A schema object is inconsistent, or cannot be translated into DDL on the platform: a duplicate or unknown column, a nullable primary key, a foreign key to an unknown table, a type or feature the platform does not support.</p><p><strong>Fix:</strong> follow the message; it names the table and the column.</p><h3 id="unknowntypeexception" tabindex="-1"><code>UnknownTypeException</code> <a class="header-anchor" href="#unknowntypeexception" aria-label="Permalink to &quot;`UnknownTypeException`&quot;">​</a></h3><p>A column type that is not registered in the <code>TypeRegistry</code>.</p><p><strong>Fix:</strong> check the name, or register the custom type (in Symfony, tag it <code>prism.type</code>).</p><h3 id="duplicatetypeexception" tabindex="-1"><code>DuplicateTypeException</code> <a class="header-anchor" href="#duplicatetypeexception" aria-label="Permalink to &quot;`DuplicateTypeException`&quot;">​</a></h3><p>A type registered twice under the same name.</p><p><strong>Fix:</strong> choose another name for the custom type.</p><h2 id="migrations" tabindex="-1">Migrations <a class="header-anchor" href="#migrations" aria-label="Permalink to &quot;Migrations&quot;">​</a></h2><p><code>Prism\\Migrations\\Exception</code>, package <code>prism-orm/migrations</code>.</p><h3 id="migrationexception" tabindex="-1"><code>MigrationException</code> <a class="header-anchor" href="#migrationexception" aria-label="Permalink to &quot;`MigrationException`&quot;">​</a></h3><p>A migration cannot run: an invalid file name, a missing class, a class that is not a migration, an unknown version, a migration already executed or not executed, a migration modified after it ran, an invalid operation, or a failure while it ran.</p><p><strong>Fix:</strong> follow the message. For a migration modified after it ran, restore it, or run <code>migrate --allow-modified</code> if the change is deliberate.</p><h3 id="irreversiblemigrationexception" tabindex="-1"><code>IrreversibleMigrationException</code> <a class="header-anchor" href="#irreversiblemigrationexception" aria-label="Permalink to &quot;`IrreversibleMigrationException`&quot;">​</a></h3><p>The <code>down()</code> of a migration that cannot be reverted: it has none, or reverting it would need data that it destroyed.</p><p><strong>Fix:</strong> none in the general case; restore a backup, or write a <code>down()</code> if the data can be rebuilt.</p><h2 id="symfony-bundle" tabindex="-1">Symfony bundle <a class="header-anchor" href="#symfony-bundle" aria-label="Permalink to &quot;Symfony bundle&quot;">​</a></h2><p><code>Prism\\Bundle\\Exception</code>, package <code>prism-orm/bundle</code>.</p><h3 id="invalidconfigurationexception" tabindex="-1"><code>InvalidConfigurationException</code> <a class="header-anchor" href="#invalidconfigurationexception" aria-label="Permalink to &quot;`InvalidConfigurationException`&quot;">​</a></h3><p><code>prism.yaml</code> is inconsistent: short and complete forms mixed, an entity manager whose connection is not declared, an unknown default entity manager.</p><p><strong>Fix:</strong> follow the message; see the <a href="/prism/reference/configuration">configuration reference</a>.</p><h3 id="mapentityexception" tabindex="-1"><code>MapEntityException</code> <a class="header-anchor" href="#mapentityexception" aria-label="Permalink to &quot;`MapEntityException`&quot;">​</a></h3><p><code>#[MapEntity]</code> is misused: an unknown entity manager, a missing route parameter, a field that does not exist. A programming error, never a 404.</p><p><strong>Fix:</strong> follow the message.</p><h3 id="makerexception" tabindex="-1"><code>MakerException</code> <a class="header-anchor" href="#makerexception" aria-label="Permalink to &quot;`MakerException`&quot;">​</a></h3><p><code>make:entity</code> or <code>make:migration</code> cannot complete: a file it cannot read, a missing class.</p><p><strong>Fix:</strong> follow the message.</p><h2 id="test-pack" tabindex="-1">Test pack <a class="header-anchor" href="#test-pack" aria-label="Permalink to &quot;Test pack&quot;">​</a></h2><h3 id="testpackexception" tabindex="-1"><code>TestPackException</code> <a class="header-anchor" href="#testpackexception" aria-label="Permalink to &quot;`TestPackException`&quot;">​</a></h3><p><code>Prism\\TestPack\\Exception\\TestPackException</code>: the test pack is misused, for example a factory used before the kernel boots, an unknown attribute, or queries counted while they are not recorded. A test error, never an application one.</p><p><strong>Fix:</strong> follow the message.</p>',129)])])}const u=t(i,[["render",r]]);export{m as __pageData,u as default};
